"""
  compute micro FP,FP,FN
  :param label_dict_accusation: a dict. {label:(TP, FP, FN)}
  :return:TP_micro,FP_micro,FN_micro
  """
def compute_TF_FP_FN_micro(label_dict: Any) -> object {
    (TP_micro, FP_micro, FN_micro) = (0.0, 0.0, 0.0);
    for (label, tuplee) in label_dict.items() {
        (TP, FP, FN) = tuplee;
        TP_micro = TP_micro + TP;
        FP_micro = FP_micro + FP;
        FN_micro = FN_micro + FN;
    }
    return (TP_micro, FP_micro, FN_micro);
}

""" Convert user-input filename for master into full name
    Mainly used to append MasterFrame directory

    Parameters
    ----------
    mdir : str
    input_name : str

    Returns
    -------
    full_name : str

    """
def user_master_name(mdir: Any, input_name: Any) -> object {
    islash = input_name.find('/');
    if (islash >= 0) {
        full_name = input_name;
    } else {
        full_name = mdir + '/' + input_name;
    }
    return full_name;
}

"""Get file format by name.

    Parameters
    ----------
    path : str
        Path to file.

    Returns
    -------
    str
        File format as a string.
    """
def _guess_format_from_name(path: Any) -> object {
    import os;
    fname = os.path.basename(path);
    if fname.endswith('.nc') {
        return 'netcdf';
    } elif fname.endswith('.asc') {
        return 'esri-ascii';
    } else {
        return None;
    }
}

